use convert_case::{Boundary, Case, Converter};
use itertools::Itertools as _;
use proc_macro::TokenStream;
use quote::quote;
use syn::{
    Attribute, Error, Expr, Ident, LitStr, Meta, Path, Result, Token,
    parse::{Parse, ParseStream, Parser},
    punctuated::Punctuated,
};

/// Documentation source for a lint rule
#[cfg(feature = "ruledocs")]
pub enum DocumentationSource {
    /// Inline documentation from doc comments
    Inline(String),
    /// Reference to a shared documentation constant
    Path(syn::Path),
}

/// Short description source for a lint rule
#[cfg(feature = "ruledocs")]
pub enum ShortDescriptionSource {
    /// Inline string literal
    Inline(LitStr),
    /// Reference to a shared short description constant
    Path(syn::Path),
}

pub struct LintRuleMeta {
    name: Ident,
    // Whether this rule should be exposed to tsgolint integration
    is_tsgolint_rule: bool,
    plugin: Ident,
    category: Ident,
    /// Describes what auto-fixing capabilities the rule has
    fix: Option<Ident>,
    #[cfg(feature = "ruledocs")]
    documentation: DocumentationSource,
    pub used_in_test: bool,
    /// Rule configuration
    /// This is the path to a struct/enum/whatever implementing
    /// schemars::JsonSchema
    config: Option<Path>,
    /// The version of oxlint in which this rule was first available.
    version: LitStr,
    /// A short, one-line summary of what the rule does.
    #[cfg(feature = "ruledocs")]
    short_description: Option<ShortDescriptionSource>,
}

impl Parse for LintRuleMeta {
    fn parse(input: ParseStream<'_>) -> Result<Self> {
        #[cfg(feature = "ruledocs")]
        let mut documentation = None;
        #[cfg(feature = "ruledocs")]
        let mut doc_comments = String::new();

        #[cfg(feature = "ruledocs")]
        let mut backtick_fences_count: usize = 0;

        for attr in input.call(Attribute::parse_outer)? {
            match parse_doc_attr(&attr)? {
                Some(value) => {
                    #[cfg(feature = "ruledocs")]
                    {
                        let line = value.strip_prefix(' ').unwrap_or(&value);
                        doc_comments.push_str(line);
                        doc_comments.push('\n');

                        // Count occurrences of "```" to ensure the markdown code blocks are closed properly.
                        backtick_fences_count += line.matches("```").count();
                    }
                    #[cfg(not(feature = "ruledocs"))]
                    {
                        let _ = value;
                    }
                }
                _ => {
                    return Err(Error::new_spanned(attr, "unexpected attribute"));
                }
            }
        }

        #[cfg(feature = "ruledocs")]
        {
            if !doc_comments.is_empty() {
                documentation.replace(DocumentationSource::Inline(doc_comments));
            }
        }

        let struct_name: Ident = input.parse()?;
        // Optional marker `(tsgolint)` directly after the rule struct name
        let mut is_tsgolint_rule = false;
        if input.peek(syn::token::Paren) {
            let content;
            syn::parenthesized!(content in input);
            let marker: Ident = content.parse()?;
            if marker == "tsgolint" {
                if !content.is_empty() {
                    return Err(Error::new_spanned(marker, "unexpected tokens after 'tsgolint'"));
                }
                is_tsgolint_rule = true;
            } else {
                return Err(Error::new_spanned(
                    marker,
                    "unsupported marker (only 'tsgolint' is allowed)",
                ));
            }
        }
        input.parse::<Token!(,)>()?;
        let plugin = input.parse()?;
        input.parse::<Token!(,)>()?;
        let category = input.parse()?;

        // Parse FixMeta if it's specified. It will otherwise be excluded from
        // the RuleMeta impl, falling back on default set by RuleMeta itself.
        // Do not provide a default value here so that it can be set there instead.
        let mut fix: Option<Ident> = None;
        let mut config: Option<Path> = None;
        let mut version: Option<LitStr> = None;
        #[cfg(feature = "ruledocs")]
        let mut short_description: Option<ShortDescriptionSource> = None;

        // remaining options are `key = value` pairs, with the exception of
        // fix kinds. Those can be short-handed to just the fix kind
        while input.peek(Token!(,)) {
            input.parse::<Token!(,)>()?;
            if input.is_empty() {
                break;
            }
            let key: Ident = input.parse()?;
            match key.to_string().as_str() {
                "fix" => {
                    if input.peek(Token!(=)) {
                        // `fix = some-fix-kind`
                        input.parse::<Token!(=)>()?;
                        fix.replace(input.parse()?);
                    } else {
                        // `fix` by itself is the same as `fix = fix`
                        fix.replace(key);
                    }
                }
                // config = path::to::StructImplementingJsonSchemaTrait
                "config" => {
                    input.parse::<Token!(=)>()?;
                    config.replace(input.parse()?);
                }
                // docs = path::to::SHARED_DOCUMENTATION_CONSTANT
                "docs" => {
                    #[cfg(feature = "ruledocs")]
                    {
                        if documentation.is_some() {
                            return Err(Error::new_spanned(
                                key,
                                "documentation source already specified inlined via doc comments",
                            ));
                        }
                        input.parse::<Token!(=)>()?;

                        documentation.replace(DocumentationSource::Path(input.parse()?));
                    }
                }
                // version = "x.y.z" or version = "next"
                "version" => {
                    input.parse::<Token!(=)>()?;
                    version.replace(input.parse()?);
                }
                // short_description = "One-line summary."
                // or short_description = path::to::SHARED_SHORT_DESCRIPTION_CONSTANT
                "short_description" => {
                    #[cfg(feature = "ruledocs")]
                    {
                        input.parse::<Token!(=)>()?;
                        if input.peek(LitStr) {
                            short_description
                                .replace(ShortDescriptionSource::Inline(input.parse()?));
                        } else {
                            short_description.replace(ShortDescriptionSource::Path(input.parse()?));
                        }
                    }
                }
                _ => {
                    if input.peek(Token!(=)) || fix.is_some() {
                        return Err(Error::new_spanned(key, "unexpected key in rule declaration"));
                    }
                    // fix kind shorthand, e.g. `dangerous-suggestion``
                    fix.replace(key);
                }
            }
        }

        let remaining = input.parse::<proc_macro2::TokenStream>()?;
        if !remaining.is_empty() {
            return Err(Error::new_spanned(
                remaining,
                "unexpected tokens in rule declaration, missing a comma?",
            ));
        }

        let Some(version) = version else {
            return Err(Error::new(
                struct_name.span(),
                "missing `version = \"x.y.z\"` or `version = \"next\"` in `declare_oxc_lint!`",
            ));
        };

        // Validate that any markdown fenced code blocks (```) in rule docs are properly closed.
        // If the total number of fences found is odd, a block was not closed.
        #[cfg(feature = "ruledocs")]
        if !backtick_fences_count.is_multiple_of(2) {
            return Err(Error::new(
                struct_name.span(),
                "unclosed markdown code block in documentation, please close all ``` fences",
            ));
        }
        #[cfg(feature = "ruledocs")]
        let Some(documentation) = documentation else {
            return Err(Error::new(
                struct_name.span(),
                "rule documentation must be specified either via doc comments or the `docs` attribute",
            ));
        };

        Ok(Self {
            name: struct_name,
            is_tsgolint_rule,
            plugin,
            category,
            fix,
            #[cfg(feature = "ruledocs")]
            documentation,
            used_in_test: false,
            config,
            version,
            #[cfg(feature = "ruledocs")]
            short_description,
        })
    }
}

pub fn rule_name_converter() -> Converter {
    Converter::new().remove_boundary(Boundary::LowerDigit).to_case(Case::Kebab)
}

pub fn declare_oxc_lint(metadata: LintRuleMeta) -> TokenStream {
    let LintRuleMeta {
        name,
        is_tsgolint_rule,
        plugin,
        category,
        fix,
        #[cfg(feature = "ruledocs")]
        documentation,
        used_in_test,
        config,
        version,
        #[cfg(feature = "ruledocs")]
        short_description,
    } = metadata;

    let canonical_name = rule_name_converter().convert(name.to_string());
    let plugin = plugin.to_string(); // ToDo: validate plugin name

    let category = match category.to_string().as_str() {
        "correctness" => quote! { RuleCategory::Correctness },
        "suspicious" => quote! { RuleCategory::Suspicious },
        "pedantic" => quote! { RuleCategory::Pedantic },
        "perf" => quote! { RuleCategory::Perf },
        "style" => quote! { RuleCategory::Style },
        "restriction" => quote! { RuleCategory::Restriction },
        "nursery" => quote! { RuleCategory::Nursery },
        _ => panic!("invalid rule category"),
    };
    let fix = fix.as_ref().map(Ident::to_string).map(|fix| {
        let fix = parse_fix(&fix);
        quote! {
            const FIX: RuleFixMeta = #fix;
        }
    });

    let import_statement = if used_in_test {
        None
    } else {
        Some(quote! {
            use crate::{rule::{RuleCategory, RuleMeta, RuleInfo, RuleFixMeta, RuleRunner}, fixer::FixKind};
            use oxc_semantic::AstTypesBitset;
        })
    };

    #[cfg(not(feature = "ruledocs"))]
    let docs: Option<proc_macro2::TokenStream> = None;

    #[cfg(feature = "ruledocs")]
    let docs = Some(match documentation {
        DocumentationSource::Inline(documentation) => quote! {
            fn documentation() -> Option<&'static str> {
                Some(#documentation)
            }
        },
        DocumentationSource::Path(shared_docs_path) => quote! {
            fn documentation() -> Option<&'static str> {
                Some(#shared_docs_path)
            }
        },
    });

    let has_config = if config.is_some() {
        quote! { const HAS_CONFIG: bool = true; }
    } else {
        quote! { const HAS_CONFIG: bool = false; }
    };

    #[cfg(not(feature = "ruledocs"))]
    let config_schema: Option<proc_macro2::TokenStream> = {
        let _ = config;
        None
    };
    #[cfg(feature = "ruledocs")]
    let config_schema = match config {
        Some(config) => Some(quote! {
            fn config_schema(generator: &mut schemars::SchemaGenerator) -> Option<schemars::schema::Schema> {
                Some(generator.subschema_for::<#config>())
            }
        }),
        None => Some(quote! {
            fn config_schema(_generator: &mut schemars::SchemaGenerator) -> Option<schemars::schema::Schema> {
                None
            }
        }),
    };

    let version_const = {
        quote! {
            const VERSION: &'static str = #version;
        }
    };

    #[cfg(not(feature = "ruledocs"))]
    let info_const: Option<proc_macro2::TokenStream> = None;

    #[cfg(feature = "ruledocs")]
    let info_const = short_description.map(|short_description| {
        let short_description = match short_description {
            ShortDescriptionSource::Inline(lit) => quote! { #lit },
            ShortDescriptionSource::Path(path) => quote! { #path },
        };
        quote! {
            const INFO: RuleInfo = RuleInfo {
                short_description: #short_description,
            };
        }
    });

    let output = quote! {
        #import_statement

        impl RuleMeta for #name {
            const NAME: &'static str = #canonical_name;

            const PLUGIN: &'static str = #plugin;

            const CATEGORY: RuleCategory = #category;

            const IS_TSGOLINT_RULE: bool = #is_tsgolint_rule;

            #fix

            #docs

            #has_config

            #config_schema

            #version_const

            #info_const
        }
    };

    TokenStream::from(output)
}

fn parse_doc_attr(attr: &Attribute) -> Result<Option<String>> {
    if let Meta::NameValue(name_value) = &attr.meta {
        let path_idents = name_value.path.segments.iter().map(|segment| &segment.ident);
        if !itertools::equal(path_idents, ["doc"]) {
            return Ok(None);
        }

        match &name_value.value {
            Expr::Lit(expr_lit) => {
                if let syn::Lit::Str(lit) = &expr_lit.lit {
                    return Ok(Some(lit.value()));
                }
            }
            Expr::Macro(expr_macro) if expr_macro.mac.path.is_ident("concat") => {
                let literals = Punctuated::<LitStr, Token![,]>::parse_terminated
                    .parse2(expr_macro.mac.tokens.clone())?;
                return Ok(Some(literals.iter().map(LitStr::value).collect()));
            }
            _ => {}
        }
    }
    Ok(None)
}

fn parse_fix(s: &str) -> proc_macro2::TokenStream {
    const SEP: char = '_';

    match s {
        "none" => {
            return quote! { RuleFixMeta::None };
        }
        "pending" => {
            return quote! { RuleFixMeta::FixPending };
        }
        "fix" => return quote! { RuleFixMeta::Fixable(FixKind::SafeFix) },
        "suggestion" => return quote! { RuleFixMeta::Fixable(FixKind::Suggestion) },
        "conditional" => {
            panic!("Invalid fix capabilities: missing a fix kind. Did you mean 'fix-conditional'?")
        }
        "None" => panic!("Invalid fix capabilities. Did you mean 'none'?"),
        "Pending" => panic!("Invalid fix capabilities. Did you mean 'pending'?"),
        "Fix" => panic!("Invalid fix capabilities. Did you mean 'fix'?"),
        "Suggestion" => panic!("Invalid fix capabilities. Did you mean 'suggestion'?"),
        invalid if !invalid.contains(SEP) => panic!(
            "invalid fix capabilities: {invalid}. Valid capabilities are none, pending, fix, suggestion, or [fix|suggestion]_[conditional?]_[dangerous?]."
        ),
        _ => {}
    }

    assert!(s.contains(SEP));

    let mut is_conditional = false;
    let fix_kinds = s
        .split(SEP)
        .filter(|seg| match *seg {
            "conditional" => {
                is_conditional = true;
                false
            }
            // e.g. "safe_fix". safe is implied
            "safe"
            // e.g. fix_or_suggestion
            | "and" | "or"
            => false,
            _ => true,
        })
        .unique()
        .map(parse_fix_kind)
        .reduce(|acc, kind| quote! { #acc.union(#kind) })
        .expect("No fix kinds were found during parsing, but at least one is required.");

    if is_conditional {
        quote! { RuleFixMeta::Conditional(#fix_kinds) }
    } else {
        quote! { RuleFixMeta::Fixable(#fix_kinds) }
    }
}

fn parse_fix_kind(s: &str) -> proc_macro2::TokenStream {
    match s {
        "fix" | "fixes" => quote! { FixKind::Fix },
        "suggestion" | "suggestions" => quote! { FixKind::Suggestion },
        "dangerous" => quote! { FixKind::Dangerous },
        _ => panic!("invalid fix kind: {s}. Valid fix kinds are fix, suggestion, or dangerous."),
    }
}

//! Calculate memory layout of all types.
//! Generate const assertions for the correctness of those calculations.
//!
//! Memory layouts are different on 64-bit and 32-bit platforms.
//! Calculate each separately, and generate assertions for each.

